#!/usr/bin/env bash
# GAP-42d — decisive canonical R1 N=1000 3-seed run with the endpoint chain ON.
#
# Design (canonical-comparable):
#   * baseline arm  : regenerated by the driver (deterministic in (seed, n)) —
#                     must reproduce the canonical 158/159/174 hits.
#   * framework arm : --restart-from-endpoint (Eq. 2 chain live).
#   * chain_off is NOT re-run: it is byte-stable (proved at N=20, GAP-42b) and
#     the canonical framework numbers 275/272/259 are exactly that arm.
#   * restart_min_nfe 20 = canonical manifest value (inert for LineageFlow —
#     the gate lives in the FlowMol3 factory).
#
# GPU 0 only. Resumable via START=<index> (replays RNG; byte-equivalent).
set -euo pipefail

REPO=/home/hugo/codes/flowa-multistep-reinference
VENV=$REPO/.venvs/lineageflow_venv/bin/python
OUT=/home/hugo/gap42d-n1000
PREMISE=/home/hugo/gap41b-nfe150/premise
N=${N:-1000}
START=${START:-0}
SEEDS=${SEEDS:-"42 43 44"}
cd "$REPO"
export TMPDIR=/home/hugo/gap41-tmp TORCHINDUCTOR_CACHE_DIR=/home/hugo/gap41-torchinductor
mkdir -p "$TMPDIR" "$TORCHINDUCTOR_CACHE_DIR" "$OUT"
cp "$PREMISE/count_hits.py" "$OUT/"

nvidia-smi > "$OUT/METADATA.gpu" 2>&1 || true
{
  echo "start=$(date -u +%FT%TZ)"
  echo "cell=R1 hmmscan_total_hits"
  echo "N=$N nfe=10 n_rounds=3 restart_min_nfe=20 scheduler=cosine temperature=1.0"
  echo "upstream_eval_len_bias=short restart_from_endpoint=TRUE"
  echo "seeds=$SEEDS start_index=$START"
  echo "canonical comparison: chain_off framework 275/272/259, baseline 158/159/174"
} > "$OUT/METADATA.txt"

for seed in $SEEDS; do
  d="$OUT/seed${seed}"
  mkdir -p "$d"
  echo "=== gen seed=$seed chain_on n=$N start=$START $(date -u +%FT%TZ) ==="
  HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1 CUDA_VISIBLE_DEVICES=0 \
    "$VENV" tools/gen_lineageflow_n1000_fastas.py \
    --seed "$seed" --n "$N" --start-index "$START" --upstream-eval-len-bias short \
    --nfe 10 --n-rounds 3 --restart-min-nfe 20 --temperature 1.0 \
    --scheduler cosine --restart-from-endpoint \
    --outdir "$d" > "$d/gen.log" 2>&1
  echo "  done $(date -u +%FT%TZ)"
done

echo "=== HMMER $(date -u +%FT%TZ) ==="
files=()
for seed in $SEEDS; do
  files+=("$OUT/seed${seed}/baseline.fasta")
  files+=("$OUT/seed${seed}/framework.fasta")
done
"$VENV" "$OUT/count_hits.py" "${files[@]}" > "$OUT/hits.txt" 2>&1
for seed in $SEEDS; do
  cp "$OUT/seed${seed}/baseline.tblout" "$OUT/seed${seed}/baseline_hits.tbl"
  cp "$OUT/seed${seed}/framework.tblout" "$OUT/seed${seed}/framework_hits.tbl"
done

echo "=== canonical baseline identity check ==="
grep "baseline.fasta" "$OUT/hits.txt" || true

echo "=== paired-t + DL meta (canonical tool) $(date -u +%FT%TZ) ==="
"$VENV" tools/r1_d004_analysis.py \
  --root "$OUT" --out "$OUT" --seeds $SEEDS --n-per-seed "$N" \
  > "$OUT/analysis.log" 2>&1 || true
tail -40 "$OUT/analysis.log"

echo "end=$(date -u +%FT%TZ)" >> "$OUT/METADATA.txt"
echo "=== ALL DONE $(date -u +%FT%TZ) ==="
cat "$OUT/hits.txt"
